function enterTu101(remember){
  if(!activeUser||!hasSubjectAccess(activeUser,"tu101"))return;
  if(state)persist();
  activeSubject="tu101";if(remember!==false)rememberSubjectSession("tu101");
  loadState();
  document.getElementById("subjectScreen").style.display="none";
  document.getElementById("appShell").style.display="block";
  const old=document.getElementById("tu101Shell");if(old)old.remove();
  const chip=document.getElementById("userChip");if(chip)chip.textContent="👤 "+activeUser.username;
  configureSubjectPanels();
  applyPathRoute();
}
enterSubject=function(subjectId,remember=true){
  if(subjectId==="tu101")return enterTu101(remember);
  if(subjectId==="ec214"){
    if(state)persist();activeSubject="ec214";loadState();configureSubjectPanels();return coreEnterSubject("ec214",remember);
  }
};
