renderSubjectHub=function(){
  coreRenderSubjectHub();ensureTu101Card();
  if(!activeUser)return;
  const yes=hasSubjectAccess(activeUser,"tu101"),card=document.getElementById("subjectTu101Card"),st=document.getElementById("subjectTu101State"),btn=document.getElementById("subjectTu101OpenBtn");
  card&&card.classList.toggle("unlocked",yes);if(st)st.textContent=yes?"Unlocked":"Locked";if(btn){btn.textContent=yes?"Open TU101":"Unlock TU101";btn.classList.toggle("secondary",yes)}
  applyPrefsEverywhere();
};
function openUnlock(subjectId){
  unlockTarget=subjectId;const panel=document.getElementById("subjectUnlockPanel"),preview=document.getElementById("subjectPreviewPanel"),input=document.getElementById("subjectPasswordInput"),status=document.getElementById("subjectUnlockStatus"),h=panel&&panel.querySelector("h2"),p=panel&&panel.querySelector("p.small");
  if(preview)preview.hidden=true;if(status)status.textContent="";if(panel)panel.hidden=false;
  if(subjectId==="tu101"){if(h)h.textContent="Enter the TU101 subject token";if(p)p.textContent="TU101 uses a separate token but the same D Study App functions and linked appearance settings.";if(input)input.placeholder="TU101 token"}
  else{if(h)h.textContent="Enter the EC214 subject password";if(p)p.textContent="Enter it once for this local account. After successful redemption, the account keeps EC214 access.";if(input)input.placeholder="Subject password"}
  setTimeout(function(){input&&input.focus()},0);
}
if(typeof DEPLOYED_SUBJECT_HASHES!=="undefined")DEPLOYED_SUBJECT_HASHES.tu101=TU101_TOKEN_HASH;
chooseSubject=function(subjectId){
  if(subjectId==="tu101"){if(hasSubjectAccess(activeUser,"tu101"))enterSubject("tu101");else openUnlock("tu101");return}
  unlockTarget="ec214";return coreChooseSubject(subjectId);
};
unlockSelectedSubject=async function(){
  const subjectId=unlockTarget||"ec214",name=subjectId==="tu101"?"TU101":"EC214",input=document.getElementById("subjectPasswordInput"),status=document.getElementById("subjectUnlockStatus"),value=input?input.value:"";
  if(!value){if(status)status.textContent="Enter the "+name+" subject "+(subjectId==="tu101"?"token.":"password.");return}
  if(await sha256Text(value)!==subjectPasswordHash(subjectId)){if(status)status.textContent="Incorrect "+name+" subject "+(subjectId==="tu101"?"token.":"password.");return}
  grantSubjectAccess(subjectId);if(input)input.value="";if(status)status.textContent="";const p=document.getElementById("subjectUnlockPanel");if(p)p.hidden=true;renderSubjectHub();enterSubject(subjectId);
};
const ub=document.getElementById("subjectUnlockBtn");if(ub)ub.onclick=unlockSelectedSubject;

applyPathRoute=function(){
  if(activeSubject!=="tu101")return coreApplyPathRoute();
  const p=location.pathname.replace(/\/+$/,"");
  if(p.endsWith("/summary")){switchTab("summary");renderTu101Summary();return}
  if(p.endsWith("/quiz")){switchTab("quiz");renderTu101QuizLayer();return}
  if(p.endsWith("/notes")){switchTab("notes");renderNotesHub();return}
  if(p.endsWith("/history")){switchTab("history");renderHistory();return}
  if(p.endsWith("/prompt")){switchTab("prompt");return}
  if(p.endsWith("/settings")){switchTab("settings");applyPrefsEverywhere();return}
  switchTab("tracker");renderTracker();
};

function sharedSettingsMarkup(scope){
  const p=sharedPrefs(),pre=scope||"shared";
  return '<div class="shared-settings-controls" data-settings-scope="'+esc(pre)+'"><div class="setting-row"><div><b>UI Theme</b><div class="small">Linked across Login, Preview, EC214, and TU101.</div></div></div><div class="ui-theme-choices shared-theme-choices"><button type="button" class="ui-theme-choice '+(p.uiTheme==="classic"?"active":"")+'" data-shared-theme="classic"><span class="ui-theme-choice-icon">◫</span><span><b>Classic</b><small>Original D Study App UI</small></span></button><button type="button" class="ui-theme-choice '+(p.uiTheme==="neo"?"active":"")+'" data-shared-theme="neo"><span class="ui-theme-choice-icon">✦</span><span><b>Neo Dashboard</b><small>Premium dashboard style</small></span></button><button type="button" class="ui-theme-choice '+(p.uiTheme==="midnight"?"active":"")+'" data-shared-theme="midnight"><span class="ui-theme-choice-icon">◈</span><span><b>Midnight Workspace</b><small>Productivity-board style</small></span></button></div><div class="setting-row"><div><b>Theme color</b></div></div><div class="swatches shared-swatches"><button type="button" class="swatch '+(p.accent==="navy"?"active":"")+'" data-color="navy" data-shared-accent="navy" title="Navy" aria-label="Navy"></button><button type="button" class="swatch '+(p.accent==="violet"?"active":"")+'" data-color="violet" data-shared-accent="violet" title="Violet" aria-label="Violet"></button><button type="button" class="swatch '+(p.accent==="forest"?"active":"")+'" data-color="forest" data-shared-accent="forest" title="Forest" aria-label="Forest"></button><button type="button" class="swatch '+(p.accent==="rose"?"active":"")+'" data-color="rose" data-shared-accent="rose" title="Rose" aria-label="Rose"></button><button type="button" class="swatch '+(p.accent==="amber"?"active":"")+'" data-color="amber" data-shared-accent="amber" title="Amber" aria-label="Amber"></button></div><div class="setting-row"><div><b>Appearance</b><div class="small">Light / Dark / follow device.</div></div><select data-shared-select="appearance"><option value="light" '+(p.appearance==="light"?"selected":"")+'>Light</option><option value="dark" '+(p.appearance==="dark"?"selected":"")+'>Dark</option><option value="system" '+(p.appearance==="system"?"selected":"")+'>System</option></select></div><div class="setting-row"><div><b>Text size</b></div><select data-shared-select="textSize"><option value="normal" '+(p.textSize==="normal"?"selected":"")+'>Normal</option><option value="large" '+(p.textSize==="large"?"selected":"")+'>Large</option></select></div><div class="setting-row"><div><b>Card style</b></div><select data-shared-select="cardStyle"><option value="soft" '+(p.cardStyle==="soft"?"selected":"")+'>Soft</option><option value="flat" '+(p.cardStyle==="flat"?"selected":"")+'>Flat</option></select></div><div class="setting-row"><div><b>Font</b></div><select data-shared-select="font"><option value="inter" '+(p.font==="inter"?"selected":"")+'>Inter</option><option value="poppins" '+(p.font==="poppins"?"selected":"")+'>Poppins</option><option value="nunito" '+(p.font==="nunito"?"selected":"")+'>Nunito Sans</option><option value="manrope" '+(p.font==="manrope"?"selected":"")+'>Manrope</option><option value="ibm" '+(p.font==="ibm"?"selected":"")+'>IBM Plex Sans</option><option value="merriweather" '+(p.font==="merriweather"?"selected":"")+'>Merriweather</option></select></div></div>';
}
function bindSharedSettings(root){
  if(!root)return;
  root.querySelectorAll("[data-shared-theme],[data-shared-accent],[data-shared-select]").forEach(function(el){el.dataset.sharedControl="1"});
  syncSharedSettingControls();
}
function syncSharedSettingControls(){
  const p=sharedPrefs();
  document.querySelectorAll("[data-shared-theme]").forEach(function(b){b.classList.toggle("active",b.dataset.sharedTheme===p.uiTheme)});
  document.querySelectorAll("[data-shared-accent]").forEach(function(b){b.classList.toggle("active",b.dataset.sharedAccent===p.accent)});
  document.querySelectorAll("[data-shared-select]").forEach(function(s){if(p[s.dataset.sharedSelect]!=null)s.value=p[s.dataset.sharedSelect]});
}
function refreshSharedSettingsSurfaces(){
  syncSharedSettingControls();
  const body=document.getElementById("globalSettingsBody");if(body){body.innerHTML=sharedSettingsMarkup("global");bindSharedSettings(body)}
  const preview=document.querySelector("#subjectPreviewBody .shared-settings-controls");if(preview){const host=preview.parentElement;host.innerHTML=sharedSettingsMarkup("preview");bindSharedSettings(host)}
}
function ensureGlobalSettings(){
  if(document.getElementById("globalSettingsBtn"))return;
  const btn=document.createElement("button");btn.id="globalSettingsBtn";btn.className="global-settings-btn secondary";btn.type="button";btn.innerHTML="⚙ Settings";document.body.appendChild(btn);
  const overlay=document.createElement("div");overlay.id="globalSettingsOverlay";overlay.className="global-settings-overlay";overlay.setAttribute("aria-hidden","true");overlay.innerHTML='<section class="global-settings-modal" role="dialog" aria-modal="true" aria-labelledby="globalSettingsTitle"><div class="global-settings-head"><div><div class="eyebrow">Linked Preferences</div><h2 id="globalSettingsTitle">Settings</h2><p class="small">One appearance setting shared across Login, Preview, EC214, and TU101 on this browser.</p></div><button class="secondary" type="button" id="globalSettingsClose">✕</button></div><div id="globalSettingsBody">'+sharedSettingsMarkup("global")+'</div><div class="global-settings-foot"><span class="small">Account PIN, backup/import, and developer controls stay in the full Settings page after sign-in.</span><button type="button" class="secondary" id="globalOpenFullSettings">Open full Settings</button></div></section>';document.body.appendChild(overlay);
  function open(){const body=document.getElementById("globalSettingsBody");body.innerHTML=sharedSettingsMarkup("global");bindSharedSettings(body);overlay.classList.add("open");overlay.setAttribute("aria-hidden","false")}
  function close(){overlay.classList.remove("open");overlay.setAttribute("aria-hidden","true")}
  btn.onclick=open;document.getElementById("globalSettingsClose").onclick=close;overlay.onclick=function(e){if(e.target===overlay)close()};
  document.getElementById("globalOpenFullSettings").onclick=function(){if(!activeUser)return;close();if(activeSubject==="tu101")location.href=APP_BASE+"/tu101/settings/";else if(activeSubject==="ec214")location.href=APP_BASE+"/settings/";else open()};
  bindSharedSettings(document.getElementById("globalSettingsBody"));
}

previewPanelMarkup=function(tab,subjectId){
  if(tab==="settings")return '<section class="panel active"><div class="panel-intro"><div><div class="eyebrow">Preferences</div><h2>Settings</h2><p>These controls are live and linked to Login, EC214, and TU101.</p></div></div><div class="settings-grid"><div class="settings-card preview-linked-settings">'+sharedSettingsMarkup("preview")+'</div><div class="settings-card"><h3>Shared instantly</h3><p class="small">Theme, appearance, text size, card style, and font update the real app immediately. Account/PIN and developer controls remain in full Settings after sign-in.</p></div></div></section>';
  if(subjectId!=="tu101")return corePreviewPanelMarkup(tab,subjectId);
  if(tab==="tracker")return '<section class="panel active preview-real-progress"><div class="dashboard-hero"><div class="dashboard-main"><div class="eyebrow">TU101 Study Dashboard</div><h2>Welcome, Preview.</h2><p>Same Progress, Notes, History, Prompt, Settings, backup, and confidence workflow as EC214. TU101 keeps its own academic state.</p><div class="quick-actions"><button class="quick-primary" disabled>Continue Summary</button><button class="quick-secondary" disabled>Open Quiz</button><button class="quick-secondary" disabled>Open All Notes</button></div></div><div class="dashboard-ring-card"><div class="small" style="text-align:center">Overall learning progress</div><div class="progress-donut" style="--pct:0"><div class="donut-center"><b>0%</b><span>weighted status</span></div></div></div><div class="dashboard-focus"><h3>Current snapshot</h3><div class="focus-line"><div class="small">Latest quiz</div><div class="focus-value">No attempt yet</div></div><div class="focus-line"><div class="small">Latest learning score</div><div class="focus-value">—</div></div><div class="focus-line"><div class="small">Confidence flags</div><div class="focus-value">—</div></div></div></div><div class="grid kpi-grid"><div class="card kpi"><div class="num">0%</div><div class="label">Overall progress</div></div><div class="card kpi"><div class="num">0</div><div class="label">Reviewed / Mastered</div></div><div class="card kpi"><div class="num">0</div><div class="label">Currently learning</div></div><div class="card kpi"><div class="num">'+TU101_TOPICS.length+'</div><div class="label">Not started</div></div></div><div class="card preview-lock-row">Lecture 1–6 progress uses the exact same status and notes workflow after unlock.</div></section>';
  if(tab==="summary")return '<section class="panel active"><div class="panel-intro"><div><div class="eyebrow">Study Notes</div><h2>TU101 Summary Library</h2><p>Academic content differs from EC214; navigation and study workflow stay the same.</p></div></div><div class="slide-card preview-summary-card"><div class="slide-no">Lecture 1 • sample</div><h2>Understanding Southeast Asia</h2><div class="keyline">Diversity and regional connection exist at the same time.</div><p>Historical migration, trade, religions, language, and hybrid cultures connect Southeast Asian societies across modern borders.</p></div></section>';
  if(tab==="quiz")return '<section class="panel active"><div class="panel-intro"><div><div class="eyebrow">Practice</div><h2>TU101 Quiz Library</h2><p>No TU101 question bank has been created yet.</p></div></div><div class="card quiz-shell"><div class="mode-switch"><button class="mode-btn active" disabled><b>Reviewing</b><span class="small">Pending</span></button><button class="mode-btn" disabled><b>Mastering</b><span class="small">Pending</span></button></div><div class="preview-lock-row">The eventual TU101 quiz will use the same notes, Not sure, Guessed, history, and Mistake Log behavior as EC214.</div></div></section>';
  const x=corePreviewPanelMarkup(tab,"ec214");return x.replaceAll("EC214","TU101").replaceAll("Economics","TU101");
};
