  previewSubjectId="tu101";previewTab="tracker";const panel=document.getElementById("subjectPreviewPanel"),title=document.getElementById("subjectPreviewTitle");if(!panel)return;panel.hidden=false;document.getElementById("subjectUnlockPanel").hidden=true;if(title)title.textContent="TU101 Preview";renderSubjectPreviewWorkspace("tu101");panel.scrollIntoView({behavior:"smooth",block:"start"});
